    INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF((v_rep IS NULL AND v_msg LIKE '%NOT attached%' AND EXISTS (SELECT 1 FROM alert_event WHERE alert_type = 'WRONG_PATIENT_REPORT' AND alert_class = 'safety_interrupt' AND source_entity_id = CAST(v_lo AS CHAR))), 'PASS', 'FAIL'), 'R7.3/R10.2', 'a report with wrong identifiers is NOT attached and an interrupt is raised', '');
  END;
