      INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R7.3', 'matching identifiers store the report with its hash and version 1', @e);
    END;
    CALL sp_attach_lab_report(v_lo, 'from_lab', '/files/r1.pdf', REPEAT('a', 64), 'patient_name', CONCAT('Zq', v_sfx, ' Sharma'), 'date_of_birth', DATE_FORMAT(v_dob, '%Y-%m-%d'), v_rep, v_msg);
    INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF((v_rep IS NOT NULL AND (SELECT version_number FROM lab_report WHERE lab_report_id = v_rep) = 1 AND (SELECT content_hash FROM lab_report WHERE lab_report_id = v_rep) = REPEAT('a', 64)), 'PASS', 'FAIL'), 'R7.3', 'matching identifiers store the report with its hash and version 1', '');
  END;
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R7.4', 'an attached report waits for the doctor review', @e);
    END;
    SELECT 1 INTO v_tmp;
    INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF((EXISTS (SELECT 1 FROM v_report_unreviewed WHERE lab_report_id = v_rep)), 'PASS', 'FAIL'), 'R7.4', 'an attached report waits for the doctor review', '');
  END;
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R10.2', 'critical mark is recorded', @e);
    END;
    CALL sp_mark_report_critical(v_rep, 'critical', 'nurse_observation', 'very high value');
    INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF(((SELECT is_critical FROM v_report_unreviewed WHERE lab_report_id = v_rep) = 1), 'PASS', 'FAIL'), 'R10.2', 'critical mark is recorded', '');
  END;
  SET @app_user_id = v_doc, @app_role = 'DOCTOR';
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R7.4', 'doctor review is its own event and clears the waiting list', @e);
    END;
    CALL sp_review_report(v_rep, 'noted, will call patient');
    INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF((NOT EXISTS (SELECT 1 FROM v_report_unreviewed WHERE lab_report_id = v_rep)), 'PASS', 'FAIL'), 'R7.4', 'doctor review is its own event and clears the waiting list', '');
  END;
  SET @app_user_id = v_rec, @app_role = 'RECEPTIONIST';
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF(@e LIKE '%consent%', 'PASS', 'FAIL'), 'R11.4', 'a family link needs a consent note', @e);
    END;
    CALL sp_create_family_link(v_visit3, v_att, 'date_of_birth', '', v_tok, v_pc, v_link);
    INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R11.4', 'a family link needs a consent note', 'no error was raised');
  END;
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R11.1/R11.3', 'link creation stores only a hash and queues a link-only SMS', @e);
    END;
    CALL sp_create_family_link(v_visit3, v_att, 'date_of_birth', 'Father Ram agreed', v_tok, v_pc, v_link);
    INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF((CHAR_LENGTH(v_tok) = 48 AND (SELECT token_hash FROM family_link WHERE family_link_id = v_link) = SHA2(v_tok, 256) AND EXISTS (SELECT 1 FROM message_outbox WHERE family_link_id = v_link AND rendered_text LIKE '%/v/%' AND rendered_text NOT LIKE '%Sharma%')), 'PASS', 'FAIL'), 'R11.1/R11.3', 'link creation stores only a hash and queues a link-only SMS', '');
  END;
  CALL sp_open_family_link(v_tok, '1900-01-01', 'test', v_out, v_vis, v_lid, v_retry);
  CALL sp_open_family_link(v_tok, '1900-01-01', 'test', v_out, v_vis, v_lid, v_retry);
  CALL sp_open_family_link(v_tok, '1900-01-01', 'test', v_out, v_vis, v_lid, v_retry);
  CALL sp_open_family_link(v_tok, '1900-01-01', 'test', v_out, v_vis, v_lid, v_retry);
  CALL sp_open_family_link(v_tok, '1900-01-01', 'test', v_out, v_vis, v_lid, v_retry);
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R11.1', 'after 5 wrong attempts even the correct DOB is locked out', @e);
    END;
    CALL sp_open_family_link(v_tok, DATE_FORMAT(v_dob, '%Y-%m-%d'), 'test', v_out, v_vis, v_lid, v_retry);
    INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF((v_out = 'locked' AND v_retry > 0 AND v_vis IS NULL), 'PASS', 'FAIL'), 'R11.1', 'after 5 wrong attempts even the correct DOB is locked out', '');
  END;
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R11.4', 'every attempt is logged (5 bad + 1 locked)', @e);
    END;
