    INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF(((SELECT COUNT(*) FROM link_access_log WHERE family_link_id = v_link) = 6), 'PASS', 'FAIL'), 'R11.4', 'every attempt is logged (5 bad + 1 locked)', '');
  END;
  CALL sp_create_family_link(v_visit3, NULL, 'date_of_birth', 'second attendant agreed', v_tok2, v_pc, v_link2);
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
