    END;
    CALL sp_open_family_link(v_tok2, DATE_FORMAT(v_dob, '%Y-%m-%d'), 'test', v_out, v_vis, v_lid, v_retry);
    INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF((v_out = 'ok' AND v_vis = v_visit3 AND v_lid = v_link2), 'PASS', 'FAIL'), 'R11.1/R11.2', 'a second link with the correct DOB opens only its own visit', '');
  END;
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R11.3', 'family views show the visit and the shareable bill without cost prices', @e);
    END;
    SELECT 1 INTO v_tmp;
    INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF(((SELECT COUNT(*) FROM v_family_visit WHERE family_link_id = v_link2) = 1 AND (SELECT COUNT(*) FROM v_family_bill WHERE family_link_id = v_link2) >= 1), 'PASS', 'FAIL'), 'R11.3', 'family views show the visit and the shareable bill without cost prices', '');
  END;
