    END;
    CALL sp_check_alerts();
    INSERT INTO t_results (outcome, rule, name, detail) VALUES ('PASS', 'R10.1', 'alert checks run without error', '');
  END;
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R10.1', 'daily summary ranks red/amber/clean checks', @e);
    END;
