    INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF(((SELECT COUNT(*) FROM v_owner_summary) >= 20 AND EXISTS (SELECT 1 FROM v_owner_summary WHERE check_code = 'approvals_waiting')), 'PASS', 'FAIL'), 'R10.1', 'daily summary ranks red/amber/clean checks', '');
  END;
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R10.4', 'owner acknowledges an interrupt once', @e);
    END;
    SELECT alert_event_id INTO v_tmp FROM alert_event WHERE alert_class = 'safety_interrupt' AND alert_type = 'EMERGENCY_OVERRIDE' ORDER BY alert_event_id DESC LIMIT 1; CALL sp_acknowledge_alert(v_tmp, 'seen');
    INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF((EXISTS (SELECT 1 FROM alert_acknowledgement WHERE alert_event_id = v_tmp)), 'PASS', 'FAIL'), 'R10.4', 'owner acknowledges an interrupt once', '');
  END;
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF(@e LIKE '%already acknowledged%', 'PASS', 'FAIL'), 'R10.4', 'a second acknowledgement is refused', @e);
    END;
    CALL sp_acknowledge_alert(v_tmp, 'again');
    INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R10.4', 'a second acknowledgement is refused', 'no error was raised');
  END;
  SET @app_user_id = v_pha, @app_role = 'PHARMACY';
