  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R5.7', 'declared cash equal to the counter-sale cash raises no difference alert', @e);
    END;
    SELECT 1 INTO v_tmp;
    INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF((NOT EXISTS (SELECT 1 FROM alert_event WHERE alert_type = 'CASH_DECLARATION_DIFF' AND source_entity_id = CAST(v_decl AS CHAR))), 'PASS', 'FAIL'), 'R5.7', 'declared cash equal to the counter-sale cash raises no difference alert', '');
  END;
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF(@e LIKE '%not allowed%', 'PASS', 'FAIL'), 'R5.7', 'only the accountant counts the cash', @e);
    END;
    CALL sp_count_cash_handover(v_decl, 6.00, 'ok');
    INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R5.7', 'only the accountant counts the cash', 'no error was raised');
  END;
  SET @app_user_id = v_acc, @app_role = 'ACCOUNTANT';
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R5.7', 'a counted amount that differs from the declaration raises an alert', @e);
    END;
    CALL sp_count_cash_handover(v_decl, 5.00, 'one note missing');
    INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF((EXISTS (SELECT 1 FROM alert_event WHERE alert_type = 'CASH_COUNT_DIFF' AND source_entity_id = CAST(v_decl AS CHAR))), 'PASS', 'FAIL'), 'R5.7', 'a counted amount that differs from the declaration raises an alert', '');
  END;
  SET @app_user_id = v_owner, @app_role = 'OWNER';
  CALL sp_delegate_authority(v_doc, 'discount', 100, NOW(3) - INTERVAL 1 MINUTE, NOW(3) + INTERVAL 1 DAY, v_dg);
  SELECT bill_id INTO v_bill3 FROM bill WHERE visit_id = v_visit3;
  SET @app_user_id = v_rec, @app_role = 'RECEPTIONIST';
  CALL sp_request_discount(v_bill3, 50, 'discount', 'regular patient', v_da1);
  CALL sp_request_discount(v_bill3, 500, 'discount', 'big discount', v_da2);
  SET @app_user_id = v_doc, @app_role = 'DOCTOR';
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R2.3/R8.4', 'a delegated doctor approves a discount inside his limit', @e);
    END;
    CALL decide_approval(v_da1, 'APPROVED', 'ok');
    INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF((approval_is_valid(v_da1, 'discount,free_service') = 1), 'PASS', 'FAIL'), 'R2.3/R8.4', 'a delegated doctor approves a discount inside his limit', '');
  END;
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF(@e LIKE '%not allowed to approve%', 'PASS', 'FAIL'), 'R2.3/G6', 'the same doctor cannot approve above the delegated limit', @e);
    END;
    CALL decide_approval(v_da2, 'APPROVED', 'ok');
    INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'R2.3/G6', 'the same doctor cannot approve above the delegated limit', 'no error was raised');
  END;
  SET @app_user_id = v_rec, @app_role = 'RECEPTIONIST';
  CALL request_approval_ex('refund', NULL, v_bill3, NULL, NULL, NULL, 10, NULL, NULL, 'refund test', v_da3);
  SET @app_user_id = v_doc, @app_role = 'DOCTOR';
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF(@e LIKE '%not allowed to approve%', 'PASS', 'FAIL'), 'G6', 'a discount delegation does not cover a refund request', @e);
    END;
    CALL decide_approval(v_da3, 'APPROVED', 'ok');
    INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'G6', 'a discount delegation does not cover a refund request', 'no error was raised');
  END;
  SET @app_user_id = v_owner, @app_role = 'OWNER';
  CALL sp_revoke_delegation(v_dg, 'test over');
  SET @app_user_id = v_rec, @app_role = 'RECEPTIONIST';
  CALL sp_request_discount(v_bill3, 20, 'discount', 'another', v_da4);
  SET @app_user_id = v_doc, @app_role = 'DOCTOR';
  BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
      GET DIAGNOSTICS CONDITION 1 @e = MESSAGE_TEXT;
      INSERT INTO t_results (outcome, rule, name, detail) VALUES (IF(@e LIKE '%not allowed to approve%', 'PASS', 'FAIL'), 'G6', 'a revoked delegation no longer works', @e);
    END;
    CALL decide_approval(v_da4, 'APPROVED', 'ok');
    INSERT INTO t_results (outcome, rule, name, detail) VALUES ('FAIL', 'G6', 'a revoked delegation no longer works', 'no error was raised');
  END;
  SET @app_user_id = NULL, @app_role = NULL;
  SELECT outcome, rule, name, detail FROM t_results ORDER BY seq;
  SELECT CONCAT(SUM(outcome = 'PASS'), ' passed, ', SUM(outcome = 'FAIL'), ' failed') AS summary FROM t_results;
END$$
DELIMITER ;
CALL t_run_rule_tests();
DROP PROCEDURE t_run_rule_tests;
